UPDATE rpt03_week
   SET rpt03_week_start_date = #{req.weekStartDate}
     , rpt03_week_close_date = #{req.weekCloseDate}
     , rpt03_biz_type        = #{req.bizType}
     , rpt03_content         = #{req.content}
     , rpt03_due_date        = #{req.dueDate}
     , rpt03_seq             = #{req.seq}
     , rpt03_bold            = #{req.bold}::text
     , rpt03_note            = #{req.note}
 WHERE rpt03_week_id   = #{req.weekId}
   AND rpt03_company_id = #{companyId}
   AND rpt03_person_id  = #{personId}

UPDATE rpt03_week
   SET rpt03_seq = #{seq}
 WHERE rpt03_week_id   = #{weekId}
   AND rpt03_company_id = #{companyId}
   AND rpt03_person_id  = #{personId}

UPDATE rpt03_week
   SET rpt03_fix_yn = #{fixYn}
 WHERE rpt03_week_id   = #{weekId}
   AND rpt03_company_id = #{companyId}
   AND rpt03_person_id  = #{personId}

UPDATE rpt03_week
   SET rpt03_bold = #{bold}
 WHERE rpt03_week_id   = #{weekId}
   AND rpt03_company_id = #{companyId}
   AND rpt03_person_id  = #{personId}

