mapper.insert:
WITH upsert AS
(
UPDATE rpt05_week_biz_class
   SET rpt05_un_use_yn     = #{unUseYn}
 WHERE rpt05_company_id    = #{companyId}
   AND rpt05_person_id     = #{personId}
   AND rpt05_week_biz_type = #{weekBizType}
 RETURNING *
)
INSERT INTO rpt05_week_biz_class
     ( rpt05_week_biz_class_id, rpt05_company_id, rpt05_person_id, rpt05_week_biz_type, rpt05_un_use_yn )
SELECT f_create_seq(), #{companyId}, #{personId}, #{weekBizType}, #{unUseYn}
 WHERE NOT EXISTS ( SELECT * FROM upsert )

